        storeAccFundingFees(pairIndex);

        PairFundingFeesV2 storage p = pairFundingFees[pairIndex];
        p.hillInflectionPoint = hillInflectionPoint.toInt64();
        p.hillPosScale = hillPosScale.toUint16();
